    def content_hash(content):
        serialized = json.dumps(
            content, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        return hashlib.sha256(serialized).hexdigest()

    for version, status in (
        ("CSA_TERMS_V1", "archived"),
        ("CSA_TERMS_V2", "published"),
    ):
        localized = seed_terms[version]
        document = document_model.objects.create(
            version=version,
            status=status,
            title_vi=localized["vi"]["title"],
            title_en=localized["en"]["title"],
            content_hash_vi=content_hash(localized["vi"]),
            content_hash_en=content_hash(localized["en"]),
            published_slot=True if status == "published" else None,
        )
        sections_en = {section["key"]: section for section in localized["en"]["sections"]}
        clause_model.objects.bulk_create(
            [
                clause_model(
                    document=document,
                    key=section_vi["key"],
                    sort_order=index * 10,
                    heading_vi=section_vi["heading"],
                    heading_en=sections_en[section_vi["key"]]["heading"],
                    paragraphs_vi=section_vi["paragraphs"],
                    paragraphs_en=sections_en[section_vi["key"]]["paragraphs"],
                )
                for index, section_vi in enumerate(localized["vi"]["sections"], start=1)
            ]
        )


